/*--------------------------------
  HOLOGRAPHIC OCEAN INSTALLATION
--------------------------------*/

#define PI 3.1415926535897932384626433832795

// WAVE DRAWING FUNCTION
vec4 wave(vec2 uv, float thic, float xoff, float yoff, float freq, float amp, float blur, float speed, vec3 colour) {
    return vec4(
        colour, 
        smoothstep(
            .001 / iResolution.y, 
            -abs(uv.x * blur), 
            abs(yoff + (amp/2. * cos(uv.x * freq * PI + (iTime * speed) + xoff)) - uv.y) - thic)
    );
}

// CIRCLE FUNCTION
vec4 circle(vec2 uv, vec2 pos, float rad, vec3 col, bool edg, float smt) {
    float value = distance(pos, uv);

    if (edg) // Smooth edges mode
        value = smoothstep(value, value + smt, rad);
    else     // Hard edges mode
        value = step(value, rad);

    return vec4(col, value);
}

// ROTATION FUNCTION
mat2 rotate2d(float _angle){
    return mat2(cos(_angle), -sin(_angle),
                sin(_angle), cos(_angle));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    // Aspect Ratio Fix
    uv = uv * 2. - 1.;
    uv.x *= iResolution.x/iResolution.y;

    // UV Rotation
    uv *= rotate2d(sin(iTime * PI/2.)/10.);

    // Time varying pixel color
    vec3 col = 0.5 + 0.5*cos(iTime+uv.xyx+vec3(0,2,4));

    // Black background
    vec4 background = vec4(0., 0., 0., 0.);
    vec4 foreground;

    // Draw waves
    int waveCount = 100;
    for(int i = 1; i < waveCount; i++) {
        float j = float(i);

        // Shine layer
        col = 0.5 + 0.5 * cos(iTime + (0.05 * j) + uv.xyx + vec3(0, 2, 4));
        foreground = wave(
            uv, 
            0.005 * (sin(iTime) + 1.5),   // Thickness
            0.05 * j,                     // X Offset
            0.66 - (0.0125 * j),          // Y Offset
            1.0 - (0.02 * j),             // Frequency
            0.25,                         // Amplitude
            0.05,                         // Edge Blur
            2.0,                          // Animation Speed
            vec3(1., 1., 1.)
        );
        background = mix(background, foreground, foreground.a);

        // Floating Ball
        if(i >= (waveCount/2 - 1)) {
            foreground = circle(
                uv,
                vec2(
                    0.,
                    i < waveCount/2 ?
                        0.15 * sin(iTime) - 0.1:
                        0.15 * sin(iTime) - 0.05
                ),
                i > waveCount/2 ?
                    0.45 - (0.02 * (j - float(waveCount)/2.)) :
                    0.4 - (0.02 * (j - float(waveCount)/2.)),
                i < waveCount/2 ?
                    col :
                    vec3(0., 0., 0.),
                i == waveCount/2 ? 
                    false : 
                    true,
                0.1
            );
            background = mix(background, foreground, foreground.a);
        }

        // Colour wave
        foreground = wave(
            uv, 
            0.005 * (sin(iTime)/2. + 1.5),   // Thickness
            0.05 * j,                        // X Offset
            0.65 - (0.0125 * j),             // Y Offset
            1.0 - (0.02 * j),                // Frequency
            0.25,                            // Amplitude
            0.015,                           // Edge Blur
            2.0,                             // Animation Speed
            col
        );
        background = mix(background, foreground, foreground.a);
    }

    // Output to screen
    fragColor = mix(background, foreground, foreground.a);
}

